  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_BIGBANG' AND description_fr IS NOT DISTINCT FROM 'Le modèle du Big Bang décrit l’évolution d’un Univers initialement très chaud et dense, en expansion depuis environ 13,8 milliards d’années. Il relie l’expansion cosmique, les éléments légers et le fond diffus cosmologique.' AND description_en IS NOT DISTINCT FROM 'The Big Bang model describes the evolution of an initially hot, dense universe expanding for about 13.8 billion years. It connects cosmic expansion, light elements and the cosmic microwave background.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_BIGBANG'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_PLANCK' AND description_fr IS NOT DISTINCT FROM 'Phase hypothétique des tout premiers instants, à l’échelle du temps de Planck, vers 10⁻⁴³ seconde. La gravitation quantique y serait essentielle ; sa description physique reste incertaine.' AND description_en IS NOT DISTINCT FROM 'A hypothetical earliest phase at the Planck timescale, around 10⁻⁴³ second. Quantum gravity would be essential, and its physical description remains uncertain.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_PLANCK'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_GUT' AND description_fr IS NOT DISTINCT FROM 'Phase théorique durant laquelle l’interaction forte et l’interaction électrofaible auraient encore été unifiées. Cette extrapolation aux très hautes énergies n’est pas confirmée expérimentalement.' AND description_en IS NOT DISTINCT FROM 'A theoretical phase in which the strong and electroweak interactions may have been unified. This extrapolation to extremely high energies has not been experimentally confirmed.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_GUT'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_ELECTROWEAK' AND description_fr IS NOT DISTINCT FROM 'Phase très précoce où les interactions électromagnétique et faible se décrivent comme une interaction électrofaible. Le refroidissement conduit à la rupture de cette symétrie.' AND description_en IS NOT DISTINCT FROM 'An early phase in which electromagnetic and weak interactions are described by the electroweak interaction. Cooling leads to the breaking of this symmetry.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_ELECTROWEAK'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_HADRON' AND description_fr IS NOT DISTINCT FROM 'En se refroidissant, le plasma primordial permet aux quarks de s’assembler en hadrons, notamment les protons et les neutrons. Cette transition prépare la formation ultérieure des noyaux atomiques.' AND description_en IS NOT DISTINCT FROM 'As the primordial plasma cools, quarks bind into hadrons, including protons and neutrons. This transition prepares the later formation of atomic nuclei.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_HADRON'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_LEPTON' AND description_fr IS NOT DISTINCT FROM 'Les leptons dominent cette phase du jeune Univers. Le refroidissement entraîne l’annihilation des électrons et positrons et le découplage des neutrinos.' AND description_en IS NOT DISTINCT FROM 'Leptons dominate this early phase of the universe. Cooling brings electron–positron annihilation and neutrino decoupling.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_LEPTON'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_NUCLEOSYN' AND description_fr IS NOT DISTINCT FROM 'Dans les premières minutes, protons et neutrons forment les premiers noyaux légers, surtout l’hélium, avec du deutérium et des traces de lithium. Les éléments plus lourds seront principalement produits plus tard dans les étoiles.' AND description_en IS NOT DISTINCT FROM 'During the first minutes, protons and neutrons form light nuclei, mainly helium, with deuterium and traces of lithium. Heavier elements are produced mainly later in stars.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_NUCLEOSYN'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_RECOMB' AND description_fr IS NOT DISTINCT FROM 'Environ 380 000 ans après le Big Bang, les électrons se lient aux noyaux pour former des atomes neutres. La lumière peut alors se propager plus librement : nous en observons aujourd’hui le fond diffus cosmologique.' AND description_en IS NOT DISTINCT FROM 'About 380,000 years after the Big Bang, electrons bind to nuclei to form neutral atoms. Light can then travel more freely; we observe its ancient remnant as the cosmic microwave background.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_RECOMB'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_DARK_AGES' AND description_fr IS NOT DISTINCT FROM 'Intervalle entre la formation des premiers atomes neutres et l’allumage des premières étoiles. L’Univers contient surtout du gaz d’hydrogène et d’hélium, dont les concentrations préparent les premières structures lumineuses.' AND description_en IS NOT DISTINCT FROM 'The interval between the formation of neutral atoms and the first stars. The universe consists mainly of hydrogen and helium gas, whose concentrations become the seeds of luminous structures.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_DARK_AGES'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_REION' AND description_fr IS NOT DISTINCT FROM 'La lumière énergétique des premières étoiles et galaxies ionise progressivement l’hydrogène intergalactique. Cette transformation étendue dans le temps met fin à la neutralité du gaz caractéristique des âges sombres.' AND description_en IS NOT DISTINCT FROM 'Energetic light from early stars and galaxies gradually ionizes intergalactic hydrogen. This extended transition ends the predominantly neutral state of gas during the cosmic dark ages.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_REION'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_MESOZOIC' AND description_fr IS NOT DISTINCT FROM 'Ère comprenant le Trias, le Jurassique et le Crétacé. Elle voit la diversification des dinosaures et la fragmentation progressive de la Pangée.' AND description_en IS NOT DISTINCT FROM 'The era comprising the Triassic, Jurassic and Cretaceous, marked by dinosaur diversification and the gradual breakup of Pangaea.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_MESOZOIC'; END IF;
