  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_PALEOGENE' AND description_fr IS NOT DISTINCT FROM 'Première période du Cénozoïque, après le Crétacé. Elle comprend le Paléocène, l’Éocène et l’Oligocène.' AND description_en IS NOT DISTINCT FROM 'The first period of the Cenozoic, following the Cretaceous. It comprises the Paleocene, Eocene and Oligocene.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_PALEOGENE'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_NEOGENE' AND description_fr IS NOT DISTINCT FROM 'Période du Cénozoïque comprenant le Miocène et le Pliocène. Elle succède au Paléogène et précède le Quaternaire.' AND description_en IS NOT DISTINCT FROM 'A Cenozoic period comprising the Miocene and Pliocene. It follows the Paleogene and precedes the Quaternary.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_NEOGENE'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='PER_SOLAR_SYS' AND description_fr IS NOT DISTINCT FROM 'Ensemble formé par le Soleil et les corps qui lui sont liés gravitationnellement, dont les planètes, leurs satellites, les astéroïdes et les comètes. Il s’est constitué dans un disque de gaz et de poussières il y a environ 4,6 milliards d’années.' AND description_en IS NOT DISTINCT FROM 'The Sun and the bodies gravitationally bound to it, including planets, moons, asteroids and comets. It formed from a disk of gas and dust about 4.6 billion years ago.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: PER_SOLAR_SYS'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.periods WHERE id='fd216ffa-0552-48b2-9dbf-b1a551c8bcb8' AND description_fr IS NOT DISTINCT FROM 'Ensemble de conflits territoriaux entre les républiques d’Arménie et d’Azerbaïdjan entre 1918 et 1920, dans le contexte de l’effondrement des empires russe et ottoman. Il se distingue des guerres plus récentes du Haut-Karabakh.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: fd216ffa-0552-48b2-9dbf-b1a551c8bcb8'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_SAPIENS' AND description_fr IS NOT DISTINCT FROM 'Les plus anciens fossiles attribués à Homo sapiens remontent à environ 300 000 ans en Afrique. Ce repère correspond à l’émergence progressive de notre espèce, et non à l’apparition soudaine de tous les comportements humains actuels.' AND description_en IS NOT DISTINCT FROM 'The oldest fossils attributed to Homo sapiens date to about 300,000 years ago in Africa. This marks the gradual emergence of our species, rather than the sudden appearance of all modern human behaviours.' AND date IS NOT DISTINCT FROM 'K300' AND date_years_bp IS NOT DISTINCT FROM 300000)) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_SAPIENS'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_GOE' AND description_fr IS NOT DISTINCT FROM 'Au début du Protérozoïque, l’oxygène produit par la photosynthèse commence à s’accumuler durablement dans l’atmosphère. Cette transition transforme la chimie des océans et les conditions de vie ; sa chronologie précise reste étudiée.' AND description_en IS NOT DISTINCT FROM 'Early in the Proterozoic, oxygen produced by photosynthesis begins to accumulate persistently in the atmosphere. This transition transforms ocean chemistry and living conditions; its detailed timing remains under study.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_GOE'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_HOMINIDS' AND description_fr IS NOT DISTINCT FROM 'Ce repère concerne la divergence entre la lignée humaine et celle des chimpanzés, estimée entre 8 et 6 millions d’années. Il ne correspond pas à l’origine de l’ensemble de la famille des grands singes.' AND description_en IS NOT DISTINCT FROM 'This marker concerns the divergence of the human and chimpanzee lineages, estimated at between 8 and 6 million years ago. It does not mark the origin of the entire great-ape family.' AND label_fr IS NOT DISTINCT FROM 'Premiers représentants de la lignée humaine' AND label_en IS NOT DISTINCT FROM 'Earliest members of the human lineage')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_HOMINIDS'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_MAMMALS' AND description_fr IS NOT DISTINCT FROM 'Des mammaliaformes issus des cynodontes apparaissent à la fin du Trias. Des fossiles attribués à Brasilodon, datés d’environ 225 millions d’années, éclairent cette transition ; la délimitation des tout premiers mammifères dépend des critères retenus.' AND description_en IS NOT DISTINCT FROM 'Mammaliaforms evolved from cynodont ancestors in the Late Triassic. Fossils attributed to Brasilodon, about 225 million years old, illuminate this transition; identifying the earliest mammals depends on the criteria used.' AND date IS NOT DISTINCT FROM 'M225' AND date_years_bp IS NOT DISTINCT FROM 225000000)) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_MAMMALS'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_PRIMATES' AND description_fr IS NOT DISTINCT FROM 'Des fossiles de primates proches des premiers lémuriens sont connus au début de l’Éocène, vers 55 millions d’années. Ce repère précède de très loin l’apparition du genre Homo et relève de l’histoire générale des mammifères.' AND description_en IS NOT DISTINCT FROM 'Fossils of early lemur-like primates are known from the early Eocene, around 55 million years ago. This marker long predates the genus Homo and belongs to the broader history of mammals.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_PRIMATES'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_ROME_FALL' AND description_fr IS NOT DISTINCT FROM 'Odoacre dépose Romulus Augustule le 4 septembre 476. Cette date sert de repère conventionnel à la fin de l’Empire romain d’Occident, tandis que l’Empire romain d’Orient poursuit son histoire.' AND description_en IS NOT DISTINCT FROM 'Odoacer deposes Romulus Augustulus on 4 September 476. This is a conventional marker for the end of the Western Roman Empire; the Eastern Roman Empire continues.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_ROME_FALL'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_LAND_PLANTS' AND description_fr IS NOT DISTINCT FROM 'Des spores fossiles témoignent de la présence de plantes sur les continents vers 470 millions d’années. La colonisation terrestre est un processus progressif qui transforme les sols, les paysages et les écosystèmes.' AND description_en IS NOT DISTINCT FROM 'Fossil spores record plants on land around 470 million years ago. Terrestrial colonization is a gradual process that transforms soils, landscapes and ecosystems.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_LAND_PLANTS'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_HEGIRA' AND description_fr IS NOT DISTINCT FROM 'L’Hégire désigne l’émigration de Muhammad et de ses compagnons de La Mecque vers Médine en 622. L’ère du calendrier musulman prend cette année pour origine ; son point de départ calendaire ne coïncide pas avec le jour du voyage.' AND description_en IS NOT DISTINCT FROM 'The Hijrah is Muhammad’s and his companions’ migration from Mecca to Medina in 622. The Islamic era uses that year as its origin; its calendar epoch is distinct from the day of the journey.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_HEGIRA'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_QUAT_GLAC' AND description_fr IS NOT DISTINCT FROM 'Le début du Quaternaire, vers 2,58 millions d’années, marque un repère pour l’intensification des cycles glaciaires de l’hémisphère Nord. Ces alternances de phases froides et tempérées rythment le Pléistocène.' AND description_en IS NOT DISTINCT FROM 'The beginning of the Quaternary, about 2.58 million years ago, marks a reference point for intensified Northern Hemisphere glacial cycles. Alternating cold and warmer phases characterize the Pleistocene.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_QUAT_GLAC'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='2bf8b54a-22fe-43fc-8fcf-39eada08d71d' AND description_fr IS NOT DISTINCT FROM 'En 1947, Andreï Jdanov présente le monde comme divisé en deux camps antagonistes, l’un dirigé par les États-Unis et l’autre par l’URSS. Cette doctrine accompagne la création du Kominform et affirme la réponse soviétique à la doctrine Truman.' AND description_en IS NOT DISTINCT FROM 'In 1947, Andrei Zhdanov presented the world as divided into opposing camps led by the United States and the Soviet Union. The doctrine accompanied the creation of the Cominform and the Soviet response to the Truman Doctrine.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: 2bf8b54a-22fe-43fc-8fcf-39eada08d71d'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_EDIACARA' AND description_fr IS NOT DISTINCT FROM 'Les biotes de l’Édiacarien réunissent des organismes macroscopiques à corps mou, connus notamment par les empreintes des fonds marins d’Australie. Ils témoignent d’écosystèmes complexes antérieurs à l’explosion cambrienne.' AND description_en IS NOT DISTINCT FROM 'The Ediacaran biota includes large soft-bodied organisms, known notably from impressions of ancient Australian seafloors. They record complex ecosystems preceding the Cambrian explosion.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_EDIACARA'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_LAST_GLAC' AND description_fr IS NOT DISTINCT FROM 'Vers 11 700 ans avant le présent, la transition vers l’Holocène marque la fin de la dernière période glaciaire. Les calottes ne disparaissent pas toutes : le climat entre dans une phase interglaciaire.' AND description_en IS NOT DISTINCT FROM 'Around 11,700 years ago, the transition to the Holocene marks the end of the last glacial period. Ice sheets do not all disappear; climate enters an interglacial phase.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_LAST_GLAC'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_ROME' AND description_fr IS NOT DISTINCT FROM 'La tradition romaine situe la fondation de Rome par Romulus au 21 avril 753 avant notre ère. Ce récit légendaire sert de repère chronologique ; l’urbanisation du site résulte d’une évolution plus longue.' AND description_en IS NOT DISTINCT FROM 'Roman tradition dates the founding of Rome by Romulus to 21 April 753 BCE. This legendary account provides a chronological marker; the site’s urban development was a longer process.' AND date IS NOT DISTINCT FROM '-0752-04-21T00:00:00Z' AND date_years_bp IS NOT DISTINCT FROM 2778.4750171115675)) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_ROME'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_HIMALAYA' AND description_fr IS NOT DISTINCT FROM 'La collision de la plaque indienne avec l’Eurasie, engagée il y a environ 50 millions d’années, provoque la formation de l’Himalaya et du plateau tibétain. La convergence et le soulèvement se poursuivent aujourd’hui.' AND description_en IS NOT DISTINCT FROM 'The collision of the Indian plate with Eurasia, beginning roughly 50 million years ago, builds the Himalayas and Tibetan Plateau. Convergence and uplift continue today.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_HIMALAYA'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_MOON_FORM' AND description_fr IS NOT DISTINCT FROM 'L’hypothèse dominante relie la formation de la Lune à un impact géant entre la jeune Terre et un autre corps planétaire, il y a environ 4,5 milliards d’années. Les matériaux projetés en orbite participent à l’assemblage du satellite.' AND description_en IS NOT DISTINCT FROM 'The leading hypothesis links the Moon’s formation to a giant impact between the young Earth and another planetary body about 4.5 billion years ago. Material sent into orbit contributes to assembling the satellite.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_MOON_FORM'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_SOLAR_NEB' AND description_fr IS NOT DISTINCT FROM 'L’effondrement d’un nuage interstellaire de gaz et de poussières donne naissance à une protoétoile entourée d’un disque. Dans cette nébuleuse solaire se formeront le Soleil, les planètes et les petits corps du Système solaire.' AND description_en IS NOT DISTINCT FROM 'A cloud of interstellar gas and dust collapses into a protostar surrounded by a disk. This solar nebula gives rise to the Sun, planets and smaller bodies of the Solar System.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_SOLAR_NEB'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_PANGAEA' AND description_fr IS NOT DISTINCT FROM 'Les mouvements des plaques rapprochent progressivement la plupart des continents au Paléozoïque supérieur pour former la Pangée. Son assemblage s’étale sur des millions d’années ; sa fragmentation ultérieure ouvre notamment l’Atlantique.' AND description_en IS NOT DISTINCT FROM 'Plate motions progressively bring most continents together in the Late Paleozoic to form Pangaea. Assembly spans millions of years; its later breakup opens the Atlantic, among other ocean basins.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_PANGAEA'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_EARTH_FORM' AND description_fr IS NOT DISTINCT FROM 'La Terre s’assemble par accrétion de matière au sein du jeune Système solaire, il y a environ 4,54 milliards d’années. Les datations radiométriques de météorites et de matériaux anciens permettent d’estimer cet âge.' AND description_en IS NOT DISTINCT FROM 'Earth assembles by accretion within the young Solar System about 4.54 billion years ago. Radiometric dating of meteorites and ancient materials constrains this age.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_EARTH_FORM'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_GLOB_CLUSTERS' AND description_fr IS NOT DISTINCT FROM 'Des groupes d’étoiles très denses se constituent au début de l’histoire des galaxies. Beaucoup d’amas globulaires de la Voie lactée sont extrêmement anciens et conservent des indices sur sa formation.' AND description_en IS NOT DISTINCT FROM 'Dense groups of stars form early in galactic history. Many of the Milky Way’s globular clusters are extremely old and preserve evidence of its formation.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_GLOB_CLUSTERS'; END IF;
  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_OCEAN_FORM' AND description_fr IS NOT DISTINCT FROM 'En refroidissant, la jeune Terre devient compatible avec la présence durable d’eau liquide en surface. Les indices minéralogiques suggèrent une histoire ancienne des océans, mais leur installation ne correspond pas à une date unique précisément connue.' AND description_en IS NOT DISTINCT FROM 'As the young Earth cools, lasting liquid water becomes possible at its surface. Mineral evidence points to an early history of oceans, but their development has no single precisely established date.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_OCEAN_FORM'; END IF;
