  IF NOT (EXISTS(SELECT 1 FROM public.events WHERE id='EVT_COLUMBIA' AND description_fr IS NOT DISTINCT FROM 'Columbia, aussi appelé Nuna dans certaines reconstitutions, désigne un ancien rassemblement continental du Paléoprotérozoïque. Sa géométrie et les étapes de son assemblage, autour de 1,8 milliard d’années, restent des sujets de recherche.' AND description_en IS NOT DISTINCT FROM 'Columbia, also called Nuna in some reconstructions, is an ancient Paleoproterozoic continental assembly. Its geometry and stages of assembly around 1.8 billion years ago remain research topics.')) THEN RAISE EXCEPTION 'Later content edits prevent rollback: EVT_COLUMBIA'; END IF;
